--
-- 資料表結構 `equipments`
--

CREATE TABLE `equipments` (
  `equipment_id` bigint(20) UNSIGNED NOT NULL COMMENT '器材編號(自動流水號)',
  `equipment_code` varchar(5) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '器材代碼(例: A1, B2)',
  `operation_status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '營運狀態: 1=可借用、2=已借出、3=維修中、4=停用中、5=已淘汰',
  `operation_remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '營運備註',
  `added_date` date DEFAULT NULL COMMENT '入庫日期',
  `maintenance_count` int(11) NOT NULL DEFAULT '0' COMMENT '維修次數',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

