--
-- 資料表結構 `equipment_certificates`
--

CREATE TABLE `equipment_certificates` (
  `certificate_id` bigint(20) UNSIGNED NOT NULL COMMENT '證照編號',
  `holder_id` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '持有者編號(學號/教職員編號)',
  `issue_date` date NOT NULL COMMENT '發照日期',
  `valid_until` date NOT NULL COMMENT '有效日期',
  `validity_status` enum('valid','expired') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'valid' COMMENT '證照有效狀態',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ;

