--
-- 資料表結構 `equipment_maintenance`
--

CREATE TABLE `equipment_maintenance` (
  `maintenance_id` bigint(20) UNSIGNED NOT NULL COMMENT '維修編號',
  `equipment_id` bigint(20) UNSIGNED NOT NULL COMMENT '關聯器材(器材編號)',
  `reporter_id` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '報修人編號(學號/教職員編號)',
  `reported_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '報修時間',
  `fault_description` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '故障描述',
  `maintenance_status` enum('pending','in_progress','completed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT '報修狀態',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `photo_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '上傳照片路徑'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

