--
-- 資料表結構 `reservations`
--

CREATE TABLE `reservations` (
  `reservation_id` bigint(20) UNSIGNED NOT NULL COMMENT '預約編號',
  `user_id` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '申請人編號(學號/教職員編號)',
  `proposal_file` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '上傳之活動企劃書檔案路徑',
  `proposal_uploaded_at` datetime DEFAULT NULL COMMENT '活動企劃書上傳時間',
  `submitted_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '送出時間(先送先審)',
  `borrow_start_at` datetime DEFAULT NULL,
  `borrow_end_at` datetime DEFAULT NULL,
  `approval_status` enum('pending','approved','rejected','need_revision','revision_overdue') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `revision_deadline` datetime DEFAULT NULL COMMENT '補件期限',
  `revision_data_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '補件時的原始申請數據(JSON格式)',
  `returned_at` datetime DEFAULT NULL COMMENT '歸還完成時間',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `rejection_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '拒絕原因',
  `draft_data` text COLLATE utf8mb4_unicode_ci COMMENT '草稿表單資料 JSON',
  `approval_stage` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '目前審核階段：a,b,c,3',
  `organization_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '單位名稱 / 主辦社團',
  `activity_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '活動名稱',
  `participant_count` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '活動對象人數',
  `staff_count` int(11) DEFAULT NULL COMMENT '工作人員人數',
  `club_president` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '社 / 會長',
  `activity_coordinator` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '活動聯絡人',
  `coordinator_department` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '聯絡人系級',
  `coordinator_phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '聯絡人手機',
  `coordinator_other_contact` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '其他聯絡方式',
  `vehicle_entry` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '汽車進入校園',
  `setup_flags` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否插旗',
  `flag_details` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '插旗地點及數量',
  `purpose` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '借用用途',
  `return_notified` tinyint(1) DEFAULT '0',
  `certificate_id` bigint(20) UNSIGNED DEFAULT NULL COMMENT '證照編號',
  `checked_in_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '報到時間'
